import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import {
  Button,
  Tabs,
  getActiveCompanyCode,
  dispatchAppToast,
  DEFAULT_PAGE_SIZE,
  type ListPageSize,
} from '@linm-soft-org/linm-web-common-components';
import {
  AccountSearchInput,
  createAccountSearchConfig,
  erpFinanceAccountSearchApi,
  useAccountSearchAsOfDate,
} from '../../../../../components/search';
import { formatAccountDisplay } from '../../../../../components/search/accountSearchApi';
import { useVoucherFormShellHeight } from '../../../../../components/form';
import {
  VoucherListPagination,
  normalizeListPageSize,
} from '../../../../../components/list/VoucherListPagination';
import { createPostingReasonSearchConfig } from '../../../../../features/kt/cash-voucher/shared/search/cashVoucherStaticSearchConfig';
import { mapPostingReasonRuleToInitItem } from '../../../../../utils/postingReasonVoucherAccess';
import type {
  BankStatementImportVoucher,
  BankStatementImportStatementLine,
} from '../../../../../services/kt/bankStatementImportModels';
import { bankStatementImportService } from '../../../../../services/kt/bankStatementImportService';
import { ktService } from '../../../../../services/kt/ktService';
import type { PostingReasonInitItem } from '../../../../../services/voucherInit/endpoint';
import { useAppDispatch } from '../../../../../store/hooks';
import { getApiErrorMessage } from '../../../../../utils/getApiErrorMessage';
import df from '../../../../../styles/documentForm.module.css';
import { ClassifyLinesGrid } from './ClassifyLinesGrid';
import {
  createCompanyCodeSearchConfig,
  createCostCodeSearchConfig,
  loadCompanyCodeMap,
  type CompanyCodeLookupItem,
} from './createClassifyLookupConfigs';
import { filterPostingReasonsByBankAccount } from './filterPostingReasonsByBankAccount';
import styles from './StepClassifyImp.module.css';

type ClassifyTab = 'thu' | 'chi' | 'dinh-khoan';

const CLASSIFY_TABS = [
  { id: 'thu', label: 'Thu' },
  { id: 'chi', label: 'Chi' },
  { id: 'dinh-khoan', label: 'Định khoản' },
] as const;

interface Props {
  voucher: BankStatementImportVoucher;
  onSaved: (voucher: BankStatementImportVoucher) => void;
  onBack: () => void;
}

function isThuLine(l: BankStatementImportStatementLine): boolean {
  if ((l.creditAmount ?? 0) > 0) return true;
  if ((l.debitAmount ?? 0) > 0) return false;
  if (l.suggestedVoucherType === 'bao_co') return true;
  if (l.suggestedVoucherType === 'bao_no') return false;
  return (l.amount ?? 0) > 0;
}

function isChiLine(l: BankStatementImportStatementLine): boolean {
  if ((l.debitAmount ?? 0) > 0) return true;
  if ((l.creditAmount ?? 0) > 0) return false;
  if (l.suggestedVoucherType === 'bao_no') return true;
  if (l.suggestedVoucherType === 'bao_co') return false;
  return (l.amount ?? 0) > 0 && !(l.creditAmount);
}

function withDefaultCompany(
  lines: BankStatementImportStatementLine[],
  voucherCompany: string,
): BankStatementImportStatementLine[] {
  const fallback = (getActiveCompanyCode() || voucherCompany || '').trim();
  if (!fallback) return lines;
  return lines.map(l => ({
    ...l,
    companyCode: (l.companyCode || '').trim() || fallback,
  }));
}

const StepClassifyImp: React.FC<Props> = ({ voucher, onSaved, onBack }) => {
  const dispatch = useAppDispatch();
  const shellRef = useRef<HTMLDivElement>(null);
  useVoucherFormShellHeight(shellRef);

  const [lines, setLines] = useState<BankStatementImportStatementLine[]>(() =>
    withDefaultCompany(voucher.statementLines, voucher.companyCode),
  );
  const [defaultBank, setDefaultBank] = useState(voucher.defaultBankAccountCode || '1121');
  const [bankAccountName, setBankAccountName] = useState('');
  const [tab, setTab] = useState<ClassifyTab>('thu');
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [allReasons, setAllReasons] = useState<PostingReasonInitItem[]>([]);
  const [page, setPage] = useState(1);
  const [pageSize, setPageSize] = useState<ListPageSize>(DEFAULT_PAGE_SIZE);
  const [companyByCode, setCompanyByCode] = useState<Map<string, CompanyCodeLookupItem>>(
    () => new Map(),
  );

  useEffect(() => {
    setLines(withDefaultCompany(voucher.statementLines, voucher.companyCode));
    setDefaultBank(voucher.defaultBankAccountCode || '1121');
  }, [voucher]);

  useEffect(() => {
    setPage(1);
  }, [tab]);

  useEffect(() => {
    let cancelled = false;
    const load = async () => {
      try {
        const [thuRules, chiRules] = await Promise.all([
          ktService.getPostingReasonRules({ voucherTypeCode: 'phieu-thu', isCash: false }),
          ktService.getPostingReasonRules({ voucherTypeCode: 'phieu-chi', isCash: false }),
        ]);
        if (cancelled) return;
        const mapped = [...(thuRules ?? []), ...(chiRules ?? [])].map(mapPostingReasonRuleToInitItem);
        setAllReasons(mapped);
      } catch {
        if (!cancelled) setAllReasons([]);
      }
    };
    const t = window.setTimeout(load, 0);
    return () => {
      cancelled = true;
      window.clearTimeout(t);
    };
  }, []);

  const filteredReasons = useMemo(
    () => filterPostingReasonsByBankAccount(allReasons, defaultBank),
    [allReasons, defaultBank],
  );

  const postingReasonSearchConfig = useMemo(
    () => createPostingReasonSearchConfig(filteredReasons),
    [filteredReasons],
  );

  const postingReasonByCode = useMemo(
    () => new Map(filteredReasons.map(r => [r.code, r])),
    [filteredReasons],
  );

  const costCodeSearchConfig = useMemo(() => createCostCodeSearchConfig(), []);

  const companyCodeSearchConfig = useMemo(
    () => createCompanyCodeSearchConfig([voucher.companyCode]),
    [voucher.companyCode],
  );

  useEffect(() => {
    let cancelled = false;
    const t = window.setTimeout(() => {
      loadCompanyCodeMap([voucher.companyCode]).then(map => {
        if (!cancelled) setCompanyByCode(map);
      });
    }, 0);
    return () => {
      cancelled = true;
      window.clearTimeout(t);
    };
  }, [voucher.companyCode]);

  const accountSearchOptions = useAccountSearchAsOfDate(undefined);
  const accountSearchConfig = useMemo(
    () => createAccountSearchConfig(accountSearchOptions),
    [accountSearchOptions],
  );

  const thuLines = useMemo(() => lines.filter(isThuLine), [lines]);
  const chiLines = useMemo(() => lines.filter(isChiLine), [lines]);

  const activeLines = tab === 'thu' ? thuLines : tab === 'chi' ? chiLines : [];
  const activeTotal = tab === 'dinh-khoan' ? filteredReasons.length : activeLines.length;

  const pagedLines = useMemo(() => {
    const start = (page - 1) * pageSize;
    return activeLines.slice(start, start + pageSize);
  }, [activeLines, page, pageSize]);

  const pagedReasons = useMemo(() => {
    const start = (page - 1) * pageSize;
    return filteredReasons.slice(start, start + pageSize);
  }, [filteredReasons, page, pageSize]);

  const rowOffset = (page - 1) * pageSize;

  useEffect(() => {
    const totalPages = Math.max(1, Math.ceil(activeTotal / pageSize));
    if (page > totalPages) setPage(totalPages);
  }, [activeTotal, page, pageSize]);

  const totals = useMemo(() => {
    let credit = 0;
    let debit = 0;
    let fee = 0;
    let tax = 0;
    for (const l of lines) {
      credit += l.creditAmount ?? 0;
      debit += l.debitAmount ?? 0;
      fee += l.feeAmount ?? 0;
      tax += l.taxAmount ?? 0;
    }
    return { credit, debit, fee, tax, count: lines.length };
  }, [lines]);

  const showFeeTaxColumns = totals.fee > 0 || totals.tax > 0;

  const patch = useCallback((id: string, patchRow: Partial<BankStatementImportStatementLine>) => {
    setLines(prev => prev.map(l => (l.id === id ? { ...l, ...patchRow } : l)));
  }, []);

  const handleSave = async () => {
    setSaving(true);
    setError(null);
    try {
      const updated = await bankStatementImportService.updateClassify(voucher.id, {
        defaultBankAccountCode: defaultBank,
        statementLines: lines.map(l => ({
          id: l.id,
          customerCode: l.customerCode,
          customerName: l.customerName,
          postingReasonCode: l.postingReasonCode,
          contraAccountCode: l.contraAccountCode,
          costCode: l.costCode,
          companyCode: l.companyCode,
        })),
      });
      dispatchAppToast(dispatch, { type: 'success', message: 'Đã lưu phân loại giao dịch' });
      onSaved(updated);
    } catch (err: unknown) {
      setError(getApiErrorMessage(err, 'Không lưu được phân loại'));
    } finally {
      setSaving(false);
    }
  };

  const tid = (s: string) => `kt-import-sao-ke-classify-${s}`;

  return (
    <div
      ref={shellRef}
      className={`${df.pageVoucher} ${styles.root}`}
      data-voucher-form-shell
      data-testid="kt-import-sao-ke-step-classify"
    >
      <div className={df.pageFormHeader}>
        <div className={styles.toolbarRow}>
          <div className={styles.titleBlock}>
            <h1 className={styles.title}>
              Phân loại giao dịch — {voucher.code}
              <span className={styles.levelPill}>Mức XL: {voucher.processingLevel}</span>
            </h1>
            <div className={styles.meta}>
              {voucher.importedByName || voucher.importedByEmployeeCode || '—'}
              {' · '}
              {voucher.monthCode}
              {' · '}
              Đơn vị {voucher.companyCode || getActiveCompanyCode() || '—'}
            </div>
          </div>
          <div className={styles.toolbarActions}>
            <Button variant="secondary" onClick={onBack} disabled={saving} data-testid={tid('back')}>
              Quay lại
            </Button>
            <Button variant="primary" onClick={handleSave} loading={saving} data-testid={tid('save')}>
              Lưu phân loại → tiếp
            </Button>
          </div>
        </div>

        <div className={`${df.section} ${styles.headerFields}`}>
          <div className={styles.field} data-testid={tid('field-voucherCode')}>
            <span className={styles.label}>Số chứng từ</span>
            <div className={styles.roValue}>{voucher.code}</div>
          </div>
          <div className={styles.field} data-testid={tid('field-bankAccount')}>
            <span className={styles.label}>TK ngân hàng (ĐK)</span>
            <AccountSearchInput
              api={erpFinanceAccountSearchApi}
              config={accountSearchConfig}
              value={defaultBank}
              primaryDisplay={formatAccountDisplay(defaultBank, bankAccountName)}
              onChange={a => {
                setDefaultBank(a.code);
                setBankAccountName(a.name);
              }}
              onClear={() => {
                setDefaultBank('1121');
                setBankAccountName('');
              }}
              showLabel={false}
              showSecondaryInput={false}
              placeholder="TK ngân hàng..."
            />
          </div>
        </div>

        <div className={styles.tabsWrap} data-testid={tid('tabs')}>
          <Tabs
            tabs={[...CLASSIFY_TABS]}
            activeTab={tab}
            onTabChange={id => setTab(id as ClassifyTab)}
            variant="underline"
          />
        </div>
      </div>

      <div className={`${df.pageFormScroll} ${styles.formScroll}`} data-testid={tid('form-scroll')}>
        {tab === 'thu' && (
          <ClassifyLinesGrid
            lines={pagedLines}
            rowOffset={rowOffset}
            showFeeTaxColumns={showFeeTaxColumns}
            postingReasonSearchConfig={postingReasonSearchConfig}
            postingReasonByCode={postingReasonByCode}
            costCodeSearchConfig={costCodeSearchConfig}
            companyCodeSearchConfig={companyCodeSearchConfig}
            companyByCode={companyByCode}
            onPatch={patch}
            testIdPrefix={tid('thu')}
          />
        )}
        {tab === 'chi' && (
          <ClassifyLinesGrid
            lines={pagedLines}
            rowOffset={rowOffset}
            showFeeTaxColumns={showFeeTaxColumns}
            postingReasonSearchConfig={postingReasonSearchConfig}
            postingReasonByCode={postingReasonByCode}
            costCodeSearchConfig={costCodeSearchConfig}
            companyCodeSearchConfig={companyCodeSearchConfig}
            companyByCode={companyByCode}
            onPatch={patch}
            testIdPrefix={tid('chi')}
          />
        )}
        {tab === 'dinh-khoan' && (
          <div className={`${df.section} ${styles.postingPanel} ${styles.linesFill}`} data-testid={tid('posting-panel')}>
            <p className={styles.hint}>
              Danh sách định khoản nghiệp vụ chỉ gồm reason có Nợ hoặc Có gắn TK{' '}
              <strong>{defaultBank || '1121'}</strong> (Thu/Chi ngân hàng). Đổi TK ở header để lọc lại.
            </p>
            <div className={`${df.tableWrapper} ${styles.tableScroll}`}>
              <table className={styles.reasonTable}>
                <thead>
                  <tr>
                    <th>Mã</th>
                    <th>Tên</th>
                    <th>TK Nợ</th>
                    <th>TK Có</th>
                  </tr>
                </thead>
                <tbody>
                  {pagedReasons.length === 0 ? (
                    <tr>
                      <td colSpan={4} className={styles.emptyCell}>
                        Chưa có định khoản khớp TK {defaultBank || '1121'}
                      </td>
                    </tr>
                  ) : (
                    pagedReasons.map(r => (
                      <tr key={r.code}>
                        <td>{r.code}</td>
                        <td>{r.name}</td>
                        <td>{r.erpDebitAccountCode || r.debitAccountCode}</td>
                        <td>{r.erpCreditAccountCode || r.creditAccountCode}</td>
                      </tr>
                    ))
                  )}
                </tbody>
              </table>
            </div>
          </div>
        )}
      </div>

      <div className={df.pageFormFooter} data-testid={tid('form-footer')}>
        <div className={df.footer}>
          <div className={styles.footerLeft}>
            {error && <div className={styles.error}>{error}</div>}
            <div className={styles.totals}>
              <span>Dòng: <strong>{totals.count}</strong></span>
              <span>Thu: <strong>{totals.credit.toLocaleString('vi-VN')}</strong></span>
              <span>Chi: <strong>{totals.debit.toLocaleString('vi-VN')}</strong></span>
              {showFeeTaxColumns && (
                <>
                  <span>Phí: <strong>{totals.fee.toLocaleString('vi-VN')}</strong></span>
                  <span>Thuế: <strong>{totals.tax.toLocaleString('vi-VN')}</strong></span>
                </>
              )}
              <span>ĐK filter: <strong>{filteredReasons.length}</strong></span>
            </div>
            <VoucherListPagination
              testIdPrefix={tid('lines')}
              page={page}
              totalCount={activeTotal}
              pageSize={pageSize}
              onPageChange={setPage}
              onPageSizeChange={size => {
                setPageSize(normalizeListPageSize(size));
                setPage(1);
              }}
            />
          </div>
          <div className={styles.toolbarActions}>
            <Button variant="secondary" onClick={onBack} disabled={saving} data-testid={tid('footer-back')}>
              Quay lại
            </Button>
            <Button variant="primary" onClick={handleSave} loading={saving} data-testid={tid('footer-save')}>
              Lưu phân loại → tiếp
            </Button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default StepClassifyImp;
