import React, { useMemo } from 'react';
import { SearchInput } from '@linm-soft-org/linm-web-common-components';
import type { SearchInputConfig } from '@linm-soft-org/linm-web-common-components';
import {
  AccountSearchInput,
  CustomerSearchField,
  createAccountSearchConfig,
  erpFinanceAccountSearchApi,
  useAccountSearchAsOfDate,
} from '../../../../../components/search';
import { formatAccountDisplay } from '../../../../../components/search/accountSearchApi';
import type { BankStatementImportStatementLine } from '../../../../../services/kt/bankStatementImportModels';
import type { PostingReasonInitItem } from '../../../../../services/voucherInit/endpoint';
import type { CostCodeLookupItem, CompanyCodeLookupItem } from './createClassifyLookupConfigs';
import { resolvePostingReasonAccounts } from '../../../../../features/kt/cash-voucher/shared/utils/applyPostingReasonAccounts';
import df from '../../../../../styles/documentForm.module.css';
import styles from './StepClassifyImp.module.css';

export type ClassifyLineKind = 'receipt' | 'payment';

const COL_COUNT = 13;
const COL_COUNT_WITH_FEE_TAX = 15;

function lineAmount(l: BankStatementImportStatementLine): number {
  return l.creditAmount || l.debitAmount || l.amount || 0;
}

function lineKind(l: BankStatementImportStatementLine): ClassifyLineKind {
  if ((l.creditAmount ?? 0) > 0) return 'receipt';
  if ((l.debitAmount ?? 0) > 0) return 'payment';
  if (l.suggestedVoucherType === 'bao_co') return 'receipt';
  if (l.suggestedVoucherType === 'bao_no') return 'payment';
  return 'payment';
}

function formatImportDate(raw?: string): string {
  const s = (raw || '').trim();
  if (!s) return '—';
  return s;
}

function companyPrimaryDisplay(
  code: string | undefined,
  byCode: Map<string, CompanyCodeLookupItem>,
): string {
  const c = (code || '').trim();
  if (!c) return '';
  const item = byCode.get(c.toUpperCase()) ?? byCode.get(c);
  return formatAccountDisplay(c, item?.name || item?.shortName);
}

export interface ClassifyLinesGridProps {
  lines: BankStatementImportStatementLine[];
  /** 0-based offset for STT across client pages */
  rowOffset?: number;
  /**
   * Hiện cột Phí/Thuế theo toàn bộ IMP (không theo trang/tab hiện tại).
   * Nếu không truyền — suy từ `lines` trên lưới.
   */
  showFeeTaxColumns?: boolean;
  postingReasonSearchConfig: SearchInputConfig<PostingReasonInitItem>;
  postingReasonByCode: Map<string, PostingReasonInitItem>;
  costCodeSearchConfig: SearchInputConfig<CostCodeLookupItem>;
  companyCodeSearchConfig: SearchInputConfig<CompanyCodeLookupItem>;
  companyByCode: Map<string, CompanyCodeLookupItem>;
  onPatch: (id: string, patch: Partial<BankStatementImportStatementLine>) => void;
  testIdPrefix: string;
}

export const ClassifyLinesGrid: React.FC<ClassifyLinesGridProps> = ({
  lines,
  rowOffset = 0,
  showFeeTaxColumns,
  postingReasonSearchConfig,
  postingReasonByCode,
  costCodeSearchConfig,
  companyCodeSearchConfig,
  companyByCode,
  onPatch,
  testIdPrefix,
}) => {
  const accountSearchOptions = useAccountSearchAsOfDate(undefined);
  const accountSearchConfig = useMemo(
    () => createAccountSearchConfig(accountSearchOptions),
    [accountSearchOptions],
  );

  const tid = (s: string) => `${testIdPrefix}-${s}`;
  const showFeeTax = showFeeTaxColumns
    ?? lines.some(l => (l.feeAmount ?? 0) > 0 || (l.taxAmount ?? 0) > 0);
  const colCount = showFeeTax ? COL_COUNT_WITH_FEE_TAX : COL_COUNT;

  return (
    <div className={`${df.linesSection} ${styles.linesFill}`} data-testid={tid('lines')}>
      <div className={`${df.tableWrapper} ${styles.tableScroll}`}>
        <table className={`${df.linesTable} ${styles.classifyTable}`}>
          <thead>
            <tr>
              <th style={{ width: 40 }}>#</th>
              <th style={{ width: 120 }}>Ngày</th>
              <th style={{ minWidth: 140 }}>Đối tượng</th>
              <th style={{ width: 110 }}>Số tiền</th>
              {showFeeTax && <th style={{ width: 90 }}>Phí</th>}
              {showFeeTax && <th style={{ width: 90 }}>Thuế</th>}
              <th style={{ minWidth: 220 }}>Nội dung chuyển khoản</th>
              <th style={{ minWidth: 120 }}>Mã tham chiếu</th>
              <th style={{ minWidth: 140 }}>Chứng từ gốc</th>
              <th style={{ minWidth: 100 }}>Ghi chú</th>
              <th style={{ minWidth: 160 }} title="Chọn đối tượng danh mục">Đối tượng</th>
              <th style={{ minWidth: 150 }}>Định khoản NV</th>
              <th style={{ minWidth: 120 }}>TK đối ứng</th>
              <th style={{ minWidth: 100 }}>Mã CP</th>
              <th style={{ minWidth: 140 }}>Đơn vị</th>
            </tr>
          </thead>
          <tbody>
            {lines.length === 0 ? (
              <tr>
                <td colSpan={colCount} className={styles.emptyCell}>Không có dòng trên tab này</td>
              </tr>
            ) : (
              lines.map((l, i) => {
                const absIndex = rowOffset + i;
                const reason = l.postingReasonCode
                  ? postingReasonByCode.get(l.postingReasonCode)
                  : undefined;
                const kind = lineKind(l);
                const amountClass = kind === 'receipt' ? styles.amountCredit : styles.amountDebit;
                return (
                  <tr key={l.id} className={df.lineRow} data-testid={tid(`line-${absIndex}`)}>
                    <td>{absIndex + 1}</td>
                    <td className={styles.dateCell}>{formatImportDate(l.transactionDate)}</td>
                    <td>
                      <div className={styles.counterparty}>
                        {l.counterpartyName || '—'}
                      </div>
                      {l.bankAccountCode ? (
                        <div className={styles.metaLine}>{l.bankAccountCode}</div>
                      ) : null}
                      {l.partnerBankName ? (
                        <div className={styles.metaLine}>{l.partnerBankName}</div>
                      ) : null}
                    </td>
                    <td className={`${df.tdAmount} ${amountClass}`}>
                      {lineAmount(l).toLocaleString('vi-VN')}
                    </td>
                    {showFeeTax && (
                      <td className={df.tdAmount}>
                        {(l.feeAmount ?? 0) > 0 ? (l.feeAmount ?? 0).toLocaleString('vi-VN') : '—'}
                      </td>
                    )}
                    {showFeeTax && (
                      <td className={df.tdAmount}>
                        {(l.taxAmount ?? 0) > 0 ? (l.taxAmount ?? 0).toLocaleString('vi-VN') : '—'}
                      </td>
                    )}
                    <td>
                      <div className={styles.descFull}>
                        {l.description?.trim() || '—'}
                      </div>
                    </td>
                    <td>
                      <div className={styles.refCell}>{l.referenceCode || '—'}</div>
                    </td>
                    <td>
                      <div className={styles.pathCell} title={l.importReference || undefined}>
                        {l.importReference || '—'}
                      </div>
                    </td>
                    <td>
                      <div className={styles.noteCell}>
                        {l.expenseNote?.trim() || '—'}
                      </div>
                    </td>
                    <td data-testid={tid(`line-${absIndex}-customer`)}>
                      <CustomerSearchField
                        testIdPrefix={tid(`line-${absIndex}-customer`)}
                        className={styles.lookupCell}
                        customerId={l.customerCode || ''}
                        customerCode={l.customerCode || ''}
                        customerName={l.customerName || ''}
                        singleField
                        createParcel={false}
                        defaultCustomerType="Both"
                        onSelect={c => onPatch(l.id, {
                          customerCode: c.code,
                          customerName: c.name,
                        })}
                        onClear={() => onPatch(l.id, {
                          customerCode: '',
                          customerName: '',
                        })}
                        placeholder="Đối tượng..."
                      />
                    </td>
                    <td data-testid={tid(`line-${absIndex}-posting`)}>
                      <SearchInput
                        config={postingReasonSearchConfig}
                        value={l.postingReasonCode || ''}
                        primaryDisplay={formatAccountDisplay(
                          l.postingReasonCode || '',
                          reason?.name,
                        )}
                        onChange={(r: PostingReasonInitItem) => {
                          const accounts = resolvePostingReasonAccounts(kind, r);
                          onPatch(l.id, {
                            postingReasonCode: r.code,
                            contraAccountCode: accounts.counterAccountCode || l.contraAccountCode,
                          });
                        }}
                        onClear={() => onPatch(l.id, { postingReasonCode: '' })}
                        showLabel={false}
                        showSecondaryInput={false}
                        placeholder="Định khoản..."
                        className={styles.lookupCell}
                      />
                    </td>
                    <td data-testid={tid(`line-${absIndex}-contra`)}>
                      <AccountSearchInput
                        api={erpFinanceAccountSearchApi}
                        config={accountSearchConfig}
                        className={styles.lookupCell}
                        value={l.contraAccountCode || ''}
                        primaryDisplay={l.contraAccountCode || ''}
                        onChange={a => onPatch(l.id, { contraAccountCode: a.code })}
                        onClear={() => onPatch(l.id, { contraAccountCode: '' })}
                        showLabel={false}
                        showSecondaryInput={false}
                        placeholder="TK đối ứng..."
                      />
                    </td>
                    <td data-testid={tid(`line-${absIndex}-cost`)}>
                      <SearchInput
                        config={costCodeSearchConfig}
                        value={l.costCode || ''}
                        primaryDisplay={l.costCode || ''}
                        onChange={(c: CostCodeLookupItem) => onPatch(l.id, { costCode: c.code })}
                        onClear={() => onPatch(l.id, { costCode: '' })}
                        showLabel={false}
                        showSecondaryInput={false}
                        placeholder="Mã CP..."
                        className={styles.lookupCell}
                      />
                    </td>
                    <td data-testid={tid(`line-${absIndex}-company`)}>
                      <SearchInput
                        config={companyCodeSearchConfig}
                        value={l.companyCode || ''}
                        primaryDisplay={companyPrimaryDisplay(l.companyCode, companyByCode)}
                        onChange={(c: CompanyCodeLookupItem) => onPatch(l.id, { companyCode: c.code })}
                        onClear={() => onPatch(l.id, { companyCode: '' })}
                        showLabel={false}
                        showSecondaryInput={false}
                        placeholder="Đơn vị..."
                        className={styles.lookupCell}
                      />
                    </td>
                  </tr>
                );
              })
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
};
