/**
 * Bank statement template recognition — MB / TCB / TPB / VP (+ generic).
 * Main columns are mapped by bank; STT is optional.
 * Columns after the last main column = user notes:
 *   1 col  → diễn giải chi phí (expenseNote)
 *   2+ cols → Mã + Tên khách hàng (noteCustomerCode / noteCustomerName)
 */

export type BankTemplateId = 'mb' | 'tcb' | 'tpb' | 'vp' | 'generic';

export interface BankColumnMap {
  sttIndex: number;
  dateIndex: number;
  refIndex: number;
  debitIndex: number;
  creditIndex: number;
  descriptionIndex: number;
  beneficiaryIndex: number;
  accountIndex: number;
  partnerBankIndex: number;
  /** Phí / Fee / Interest — TCB và template tương tự. */
  feeIndex: number;
  /** Thuế / Transaction VAT. */
  taxIndex: number;
  /** Cột hệ thống phía sau (phí / thuế / số dư…) — không phải note user. */
  systemTailIndices: number[];
  /** Extra user-note columns (after main). */
  noteIndices: number[];
}

export interface BankTemplateDetectResult {
  bankId: BankTemplateId;
  bankLabel: string;
  columnMap: BankColumnMap;
  headerRowIndex: number;
  headers: string[];
}

export interface ParsedBankRow {
  transactionDate?: string;
  referenceCode?: string;
  debitAmount?: number;
  creditAmount?: number;
  amount?: number;
  /** Phí NH / lãi (tuyệt đối — ngân hàng thường ghi âm khi trừ TK). */
  feeAmount?: number;
  /** Thuế / VAT giao dịch (tuyệt đối). */
  taxAmount?: number;
  counterpartyName?: string;
  description?: string;
  bankAccountCode?: string;
  partnerBankName?: string;
  /** Diễn giải chi phí (1 cột note). */
  expenseNote?: string;
  /** Mã KH từ note (2+ cột). */
  noteCustomerCode?: string;
  /** Tên KH từ note (2+ cột). */
  noteCustomerName?: string;
  bankTemplateId: BankTemplateId;
}

const BANK_LABELS: Record<BankTemplateId, string> = {
  mb: 'MB Bank',
  tcb: 'Techcombank',
  tpb: 'TPBank',
  vp: 'VPBank',
  generic: 'Sao kê chung',
};

function normHeader(h: string): string {
  return String(h ?? '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/đ/g, 'd')
    .replace(/Đ/g, 'd')
    .toLowerCase()
    .replace(/[\r\n]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function findCol(headers: string[], includes: string[], excludes: string[] = []): number {
  for (let i = 0; i < headers.length; i++) {
    const h = normHeader(headers[i]);
    if (!h) continue;
    if (!includes.some(kw => h.includes(normHeader(kw)))) continue;
    if (excludes.some(nk => h.includes(normHeader(nk)))) continue;
    return i;
  }
  return -1;
}

function scoreHeaderRow(cells: string[]): { score: number; bankHints: Partial<Record<BankTemplateId, number>> } {
  const joined = normHeader(cells.join(' | '));
  let score = 0;
  const bankHints: Partial<Record<BankTemplateId, number>> = {};

  const hits = [
    'ngay giao dich', 'transaction date',
    'phat sinh no', 'phat sinh co', 'debit', 'credit',
    'noi dung', 'details', 'dien giai', 'description',
    'so but toan', 'transaction no', 'reference',
    'ghi no', 'ghi co', 'so tien ghi no', 'so tien ghi co',
    'chi tiet giao dich', 'transaction details',
  ];
  for (const kw of hits) {
    if (joined.includes(kw)) score += 1;
  }

  if (joined.includes('remitter') || joined.includes('ngan hang doi tac') || joined.includes('beneficiary')) {
    bankHints.mb = (bankHints.mb ?? 0) + 2;
    score += 1;
  }
  if (joined.includes('requesting date') || joined.includes('ngay kh thuc hien') || joined.includes("remitter's")) {
    bankHints.tcb = (bankHints.tcb ?? 0) + 3;
    score += 2;
  }
  if (joined.includes('counter account') || joined.includes('tai khoan doi ung') || joined.includes('chu tk doi ung')) {
    bankHints.tpb = (bankHints.tpb ?? 0) + 3;
    score += 2;
  }
  if (joined.includes('virtual account') || joined.includes('running balance') || joined.includes('chi tiet giao dich')) {
    bankHints.vp = (bankHints.vp ?? 0) + 3;
    score += 2;
  }
  if (joined.includes('but toan') && joined.includes('phat sinh')) {
    bankHints.mb = (bankHints.mb ?? 0) + 1;
  }

  return { score, bankHints };
}

function detectBankId(
  headers: string[],
  fileName: string,
  folderPath: string | undefined,
  bankHints: Partial<Record<BankTemplateId, number>>,
): BankTemplateId {
  const ctx = normHeader([fileName, folderPath ?? '', ...headers].join(' '));
  const scores: Record<BankTemplateId, number> = {
    mb: bankHints.mb ?? 0,
    tcb: bankHints.tcb ?? 0,
    tpb: bankHints.tpb ?? 0,
    vp: bankHints.vp ?? 0,
    generic: 0,
  };

  if (/\b(tcb|techcombank|techcom)\b/.test(ctx)) scores.tcb += 5;
  if (/\b(tpb|tpbank|tien phong)\b/.test(ctx)) scores.tpb += 5;
  if (/\b(vpb|vpbank|vp bank)\b/.test(ctx)) scores.vp += 5;
  if (/\b(mb bank|military|mb cong ty|mb ca nhan|mbbank)\b/.test(ctx) || /(^|[^a-z])mb([^a-z]|$)/.test(ctx)) {
    scores.mb += 4;
  }

  // Header-specific boosts
  const h = normHeader(headers.join(' | '));
  if (h.includes('ngay kh thuc hien') || h.includes('requesting date')) scores.tcb += 4;
  if (h.includes('tai khoan doi ung') || h.includes('counter account')) scores.tpb += 4;
  if (h.includes('chi tiet giao dich') || h.includes('virtual account number')) scores.vp += 4;
  if (h.includes('ngan hang doi tac') || h.includes('remitter bank')) scores.mb += 3;

  let best: BankTemplateId = 'generic';
  let bestScore = 0;
  (Object.keys(scores) as BankTemplateId[]).forEach(id => {
    if (id === 'generic') return;
    if (scores[id] > bestScore) {
      bestScore = scores[id];
      best = id;
    }
  });
  return bestScore >= 2 ? best : 'generic';
}

function buildColumnMap(bankId: BankTemplateId, headers: string[]): Omit<BankColumnMap, 'noteIndices'> {
  const base = {
    sttIndex: findCol(headers, ['stt', 'no.', '(no)'], ['transaction no', 'so but toan', 'ma giao dich']),
    dateIndex: -1,
    refIndex: -1,
    debitIndex: -1,
    creditIndex: -1,
    descriptionIndex: -1,
    beneficiaryIndex: -1,
    accountIndex: -1,
    partnerBankIndex: -1,
    feeIndex: -1,
    taxIndex: -1,
    systemTailIndices: [] as number[],
  };

  if (bankId === 'tcb') {
    base.dateIndex = findCol(headers, ['ngay giao dich', 'transaction date'], ['requesting', 'ngay kh']);
    if (base.dateIndex < 0) base.dateIndex = findCol(headers, ['ngay kh thuc hien', 'requesting date']);
    base.refIndex = findCol(headers, ['so but toan', 'reference number', 'reference']);
    base.debitIndex = findCol(headers, ['no/debit', 'no / debit', 'nợ/debit', 'debit'], ['credit', 'fee', 'vat']);
    if (base.debitIndex < 0) base.debitIndex = findCol(headers, ['nợ', 'no'], ['credit', 'co', 'fee']);
    base.creditIndex = findCol(headers, ['co/credit', 'có/credit', 'credit'], ['debit', 'fee', 'vat']);
    if (base.creditIndex < 0) base.creditIndex = findCol(headers, ['có', 'co'], ['debit', 'no', 'fee']);
    base.descriptionIndex = findCol(headers, ['dien giai', 'description']);
    base.beneficiaryIndex = findCol(headers, ['ten tai khoan doi ung', "remitter's account name", 'account name']);
    base.accountIndex = findCol(headers, ['tai khoan dich', "remitter's account number", 'account number'], ['name']);
    base.partnerBankIndex = findCol(headers, ['ngan hang doi tac', "remitter's bank", 'remitter bank']);
    // TCB: "Phí/Lãi Fee/Interest" · "Thuế/Transaction VAT"
    base.feeIndex = findCol(headers, ['phi/lai', 'fee/interest', 'phi', 'fee'], ['so du', 'balance', 'total']);
    base.taxIndex = findCol(headers, ['thue', 'transaction vat', 'vat'], ['so du', 'balance', 'total']);
    const bal = findCol(headers, ['so du', 'running balance', 'balance']);
    base.systemTailIndices = [base.feeIndex, base.taxIndex, bal].filter(i => i >= 0);
    return base;
  }

  if (bankId === 'tpb') {
    base.dateIndex = findCol(headers, ['ngay giao dich', 'transaction date']);
    base.refIndex = findCol(headers, ['ma giao dich', 'transaction code']);
    base.debitIndex = findCol(headers, ['ghi no', 'debit']);
    base.creditIndex = findCol(headers, ['ghi co', 'credit']);
    base.descriptionIndex = findCol(headers, ['dien giai', 'contents', 'noi dung']);
    base.beneficiaryIndex = findCol(headers, ['chu tk doi ung', 'counter account owner']);
    base.accountIndex = findCol(headers, ['tai khoan doi ung', 'counter account']);
    base.feeIndex = findCol(headers, ['phi', 'fee'], ['so du', 'balance']);
    base.taxIndex = findCol(headers, ['thue', 'vat'], ['so du', 'balance']);
    const bal = findCol(headers, ['so du', 'balance']);
    base.systemTailIndices = [base.feeIndex, base.taxIndex, bal].filter(i => i >= 0);
    return base;
  }

  if (bankId === 'vp') {
    base.dateIndex = findCol(headers, ['ngay giao dich', 'transaction date']);
    base.refIndex = findCol(headers, ['so tham chieu', 'transaction reference', 'reference']);
    base.debitIndex = findCol(headers, ['so tien ghi no', 'debit amount', 'debit']);
    base.creditIndex = findCol(headers, ['so tien ghi co', 'credit amount', 'credit']);
    base.descriptionIndex = findCol(headers, ['chi tiet giao dich', 'transaction details', 'details']);
    base.accountIndex = findCol(headers, ['so tai khoan cap 2', 'virtual account']);
    base.feeIndex = findCol(headers, ['phi', 'fee'], ['so du', 'balance']);
    base.taxIndex = findCol(headers, ['thue', 'vat'], ['so du', 'balance']);
    const bal = findCol(headers, ['so du', 'running balance']);
    const valDate = findCol(headers, ['ngay hieu luc', 'value date']);
    const txnTime = findCol(headers, ['thoi gian giao dich', 'transaction time']);
    base.systemTailIndices = [base.feeIndex, base.taxIndex, bal, valDate, txnTime].filter(i => i >= 0);
    return base;
  }

  // MB + generic — một số template có cột phí/thuế
  base.dateIndex = findCol(headers, ['ngay giao dich', 'transaction date', 'ngay gd'], ['hach toan', 'value date']);
  if (base.dateIndex < 0) base.dateIndex = findCol(headers, ['ngay', 'date'], ['value', 'hach toan', 'ky']);
  base.refIndex = findCol(
    headers,
    ['so but toan', 'transaction no', 'but toan', 'ma giao dich', 'reference'],
    ['running'],
  );
  base.debitIndex = findCol(headers, ['phat sinh no', 'debit', 'ghi no', 'so tien ghi no'], ['phat sinh co', 'credit']);
  base.creditIndex = findCol(headers, ['phat sinh co', 'credit', 'ghi co', 'so tien ghi co'], ['phat sinh no', 'debit']);
  base.descriptionIndex = findCol(headers, ['noi dung', 'details', 'dien giai', 'chi tiet giao dich', 'description'], ['remitter']);
  base.beneficiaryIndex = findCol(headers, ['don vi thu huong', 'beneficiary', 'applicant', 'don vi chuyen']);
  base.accountIndex = findCol(headers, ['tai khoan', 'account'], ['ngan hang doi tac', 'remitter bank', 'doi ung']);
  base.partnerBankIndex = findCol(headers, ['ngan hang doi tac', 'remitter bank', 'remitter']);
  base.feeIndex = findCol(headers, ['phi', 'fee', 'charge'], ['so du', 'balance', 'total']);
  base.taxIndex = findCol(headers, ['thue', 'vat'], ['so du', 'balance', 'total']);
  const bal = findCol(headers, ['so du', 'balance'], ['dau', 'cuoi']);
  const postingDate = findCol(headers, ['ngay hach toan']);
  base.systemTailIndices = [base.feeIndex, base.taxIndex, bal, postingDate].filter(i => i >= 0);
  return base;
}

function isSystemNoteHeader(h: string): boolean {
  const n = normHeader(h);
  if (!n) return false;
  return (
    n.includes('so du')
    || n.includes('balance')
    || n.includes('phi')
    || n.includes('fee')
    || n.includes('thue')
    || n.includes('vat')
    || n.includes('lai')
    || n.includes('interest')
    || n.includes('ngay hieu luc')
    || n.includes('value date')
    || n.includes('thoi gian')
    || n.includes('virtual account')
  );
}

function detectNoteIndices(
  headers: string[],
  map: Omit<BankColumnMap, 'noteIndices'>,
  dataRows: string[][],
): number[] {
  const mainIdx = [
    map.sttIndex, map.dateIndex, map.refIndex, map.debitIndex, map.creditIndex,
    map.descriptionIndex, map.beneficiaryIndex, map.accountIndex, map.partnerBankIndex,
    map.feeIndex, map.taxIndex,
    ...map.systemTailIndices,
  ].filter(i => i >= 0);
  const lastMain = mainIdx.length ? Math.max(...mainIdx) : -1;
  const maxCols = Math.max(
    headers.length,
    ...dataRows.map(r => r.length),
    lastMain + 1,
  );

  const notes: number[] = [];
  const dataCount = Math.max(1, Math.min(dataRows.length, 80));
  for (let c = lastMain + 1; c < maxCols; c++) {
    const headerText = String(headers[c] ?? '').trim();
    if (isSystemNoteHeader(headerText)) continue;

    let nonEmpty = 0;
    for (const r of dataRows.slice(0, 80)) {
      if (String(r[c] ?? '').trim()) nonEmpty += 1;
    }
    if (!headerText && nonEmpty === 0) continue;

    // User notes are typically sparse (< 90% rows). Dense filled cols after main are usually system.
    const density = nonEmpty / dataCount;
    if (!headerText && density > 0.9) continue;

    notes.push(c);
  }
  return notes;
}

export function detectBankTemplate(
  rawRows: string[][],
  fileName: string,
  folderPath?: string,
): BankTemplateDetectResult | null {
  if (!rawRows?.length) return null;

  let bestIdx = -1;
  let bestScore = 0;
  let bestHints: Partial<Record<BankTemplateId, number>> = {};

  for (let i = 0; i < Math.min(rawRows.length, 60); i++) {
    const cells = (rawRows[i] || []).map(c => String(c ?? ''));
    const nonEmpty = cells.filter(c => c.trim()).length;
    if (nonEmpty < 3) continue;
    const { score, bankHints } = scoreHeaderRow(cells);
    if (score > bestScore) {
      bestScore = score;
      bestIdx = i;
      bestHints = bankHints;
    }
  }

  if (bestIdx < 0 || bestScore < 3) {
    // fallback: first dense row
    for (let i = 0; i < Math.min(rawRows.length, 30); i++) {
      if ((rawRows[i] || []).filter(c => String(c).trim()).length >= 3) {
        bestIdx = i;
        break;
      }
    }
  }
  if (bestIdx < 0) return null;

  const headers = (rawRows[bestIdx] || []).map(h =>
    String(h ?? '').replace(/\r?\n/g, ' ').replace(/\s+/g, ' ').trim(),
  );
  const bankId = detectBankId(headers, fileName, folderPath, bestHints);
  const baseMap = buildColumnMap(bankId, headers);

  // Sample data rows for note detection
  const dataSample = rawRows
    .slice(bestIdx + 1, bestIdx + 100)
    .map(r => (r || []).map(c => String(c ?? '')));
  const noteIndices = detectNoteIndices(headers, baseMap, dataSample);

  // Require at least date + (debit or credit or description) to be a valid statement template
  const hasCore =
    baseMap.dateIndex >= 0
    && (baseMap.debitIndex >= 0 || baseMap.creditIndex >= 0 || baseMap.descriptionIndex >= 0);
  if (!hasCore && bestScore < 4) return null;

  return {
    bankId,
    bankLabel: BANK_LABELS[bankId],
    columnMap: { ...baseMap, noteIndices },
    headerRowIndex: bestIdx,
    headers,
  };
}

export function parseAmountCell(v: string): number | undefined {
  if (!v) return undefined;
  let cleaned = String(v).trim().replace(/\s/g, '');
  if (!cleaned || cleaned === '-' || cleaned === '—') return undefined;

  const neg = cleaned.startsWith('-') || cleaned.startsWith('(');
  cleaned = cleaned.replace(/^[-(]+/, '').replace(/\)+$/, '');

  const hasComma = cleaned.includes(',');
  const dotCount = (cleaned.match(/\./g) || []).length;

  if (hasComma && dotCount > 0) {
    const lastComma = cleaned.lastIndexOf(',');
    const lastDot = cleaned.lastIndexOf('.');
    if (lastComma > lastDot) {
      cleaned = cleaned.replace(/\./g, '');
      const lc = cleaned.lastIndexOf(',');
      cleaned = `${cleaned.substring(0, lc)}.${cleaned.substring(lc + 1)}`;
    } else {
      cleaned = cleaned.replace(/,/g, '');
    }
  } else if (hasComma) {
    cleaned = cleaned.replace(/,/g, '');
  } else if (dotCount > 1) {
    cleaned = cleaned.replace(/\./g, '');
  }

  const n = parseFloat(cleaned);
  if (isNaN(n)) return undefined;
  return neg ? -Math.abs(n) : n;
}

function cell(row: string[], idx: number): string {
  if (idx < 0) return '';
  return String(row[idx] ?? '').replace(/\r?\n/g, ' ').trim();
}

/**
 * Parse one data row. Returns null if row has no usable signal (empty / separator).
 * STT is NOT required.
 */
export function parseTemplateDataRow(
  row: string[],
  map: BankColumnMap,
  bankId: BankTemplateId,
): ParsedBankRow | null {
  const date = cell(row, map.dateIndex);
  const debitRaw = cell(row, map.debitIndex);
  const creditRaw = cell(row, map.creditIndex);
  let debitAmount = parseAmountCell(debitRaw);
  let creditAmount = parseAmountCell(creditRaw);

  // VP often stores debit as negative in "debit amount" column
  if (bankId === 'vp') {
    if (debitAmount != null && debitAmount < 0) debitAmount = Math.abs(debitAmount);
    if (creditAmount != null && creditAmount < 0) creditAmount = Math.abs(creditAmount);
  }

  const description = cell(row, map.descriptionIndex);
  const referenceCode = cell(row, map.refIndex);
  const counterpartyName = cell(row, map.beneficiaryIndex);
  const bankAccountCode = cell(row, map.accountIndex);
  const partnerBankName = cell(row, map.partnerBankIndex);

  // TCB/template: phí/thuế thường âm khi trừ TK — lưu tuyệt đối cho chi tiết GD
  const feeRaw = parseAmountCell(cell(row, map.feeIndex));
  const taxRaw = parseAmountCell(cell(row, map.taxIndex));
  const feeAmount = feeRaw != null && feeRaw !== 0 ? Math.abs(feeRaw) : undefined;
  const taxAmount = taxRaw != null && taxRaw !== 0 ? Math.abs(taxRaw) : undefined;

  const hasAmount = (debitAmount != null && debitAmount !== 0) || (creditAmount != null && creditAmount !== 0);
  const hasFeeTax = feeAmount != null || taxAmount != null;
  const hasSignal = !!(date || description || referenceCode || hasAmount || counterpartyName || hasFeeTax);
  if (!hasSignal) return null;

  // Skip header-like repeats
  const dateNorm = normHeader(date);
  if (dateNorm.includes('ngay giao dich') || dateNorm.includes('transaction date')) return null;

  const notes = map.noteIndices
    .map(i => cell(row, i))
    .filter(Boolean);

  let expenseNote: string | undefined;
  let noteCustomerCode: string | undefined;
  let noteCustomerName: string | undefined;

  if (notes.length === 1) {
    expenseNote = notes[0];
  } else if (notes.length === 2) {
    noteCustomerCode = notes[0];
    noteCustomerName = notes[1];
  } else if (notes.length >= 3) {
    // e.g. VP: code | bank | name
    noteCustomerCode = notes[0];
    noteCustomerName = notes.slice(1).join(' · ');
  }

  const absDebit = debitAmount != null ? Math.abs(debitAmount) : undefined;
  const absCredit = creditAmount != null ? Math.abs(creditAmount) : undefined;
  const amount =
    absDebit && absDebit > 0 ? absDebit
      : absCredit && absCredit > 0 ? absCredit
        : undefined;

  return {
    transactionDate: date || undefined,
    referenceCode: referenceCode || undefined,
    debitAmount: absDebit && absDebit > 0 ? absDebit : undefined,
    creditAmount: absCredit && absCredit > 0 ? absCredit : undefined,
    amount,
    feeAmount,
    taxAmount,
    counterpartyName: counterpartyName || undefined,
    description: description || undefined,
    bankAccountCode: bankAccountCode || undefined,
    partnerBankName: partnerBankName || undefined,
    expenseNote,
    noteCustomerCode,
    noteCustomerName,
    bankTemplateId: bankId,
  };
}

export function bankTemplateLabel(id: BankTemplateId | undefined): string {
  return id ? BANK_LABELS[id] : BANK_LABELS.generic;
}
